const ORIGIN = 'https://coolcode.ca';
const OWNER = 911357;
const known = new Set([...toolList, 'site']);
const categories = new Set(['bug', 'data', 'accessibility', 'other']);
const variants = new Set(['a', 'b']);
const experimentName = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const encoder = new TextEncoder();
const dayOf = date => date.toISOString().slice(0,10);
const errorResponse = (status,message) => ({status, body:{error:message}});
const cacheControl = 'no-store';

async function body(request, limit) {
  if (Number(request.headers.get('content-length')) > limit) throw new RangeError();
  if (!request.body) throw new SyntaxError();
  const reader = request.body.getReader();
  const chunks = [];
  let length = 0;
  while (true) {
    const {done,value} = await reader.read();
    if (done) break;
    length += value.length;
    if (length > limit) { await reader.cancel(); throw new RangeError(); }
    chunks.push(value);
  }
  const bytes = new Uint8Array(length);
  let offset = 0;
  for (const chunk of chunks) { bytes.set(chunk,offset); offset += chunk.length; }
  const value = JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
  if (!value || Array.isArray(value) || typeof value !== 'object') throw new SyntaxError();
  return value;
}

function eventRecord(value) {
  if (!known.has(value.tool) || value.tool==='site' && value.type!=='pageview') return null;
  if (value.type==='pageview') return {type:'pageview',tool:value.tool,experiment:'',variant:''};
  if (!['impression','click'].includes(value.type) || !variants.has(value.variant) ||
      typeof value.experiment!=='string' || value.experiment.length>48 || !experimentName.test(value.experiment)) return null;
  return {type:value.type,tool:value.tool,experiment:value.experiment,variant:value.variant};
}

function reportRecord(value) {
  if (!known.has(value.tool) || !categories.has(value.category) || typeof value.description!=='string' ||
      (value.website!=null && value.website!=='') || !value.description.trim() || value.description.trim().length>2000) return null;
  return {tool:value.tool,category:value.category,description:value.description.trim()};
}

// Discard prior daily salts and expired counters the first time a new UTC day is used.
async function allowed(db, request, now, kind) {
  const day = dayOf(now);
  const ms = now.getTime();
  let salt = await db.prepare('SELECT secret FROM salts WHERE day=?').bind(day).first('secret');
  if (!salt) {
    await db.batch([
      db.prepare('INSERT OR IGNORE INTO salts(day,secret) VALUES(?,?)').bind(day,crypto.randomUUID()),
      db.prepare('DELETE FROM salts WHERE day<?').bind(day),
      db.prepare('DELETE FROM limits WHERE expiry<=?').bind(ms),
    ]);
    salt = await db.prepare('SELECT secret FROM salts WHERE day=?').bind(day).first('secret');
  }
  const addr = request.headers.get('CF-Connecting-IP') || 'shared';
  const raw = await crypto.subtle.digest('SHA-256',encoder.encode(salt+'|'+addr+'|'+kind));
  const client = Array.from(new Uint8Array(raw).slice(0,16),b=>b.toString(16).padStart(2,'0')).join('');
  const width = kind==='report' ? 3600000 : 300000;
  const maximum = kind==='report' ? 8 : 240;
  const bucket = Math.floor(ms/width);
  const record = await db.prepare(
    'INSERT INTO limits(bucket,kind,client,hits,expiry) VALUES(?,?,?,1,?) ON CONFLICT(bucket,kind,client) DO UPDATE SET hits=hits+1 WHERE hits<? RETURNING hits'
  ).bind(bucket,kind,client,(bucket+1)*width,maximum).first();
  return Boolean(record);
}

async function owner(request) {
  const auth = request.headers.get('authorization') || '';
  if (!/^Bearer [^\s]{8,512}$/i.test(auth)) return errorResponse(401,'Owner sign-in is required.');
  let response;
  try {
    response=await fetch('https://api.github.com/user',{headers:{Authorization:auth,Accept:'application/vnd.github+json','User-Agent':'CoolCode-owner-check','X-GitHub-Api-Version':'2022-11-28'},redirect:'manual',signal:AbortSignal.timeout(6000)});
    if (response.status===401) return errorResponse(401,'GitHub did not accept this sign-in.');
    if (!response.ok) return errorResponse(503,'GitHub identity check is unavailable.');
    const user=await response.json();
    if (user.id!==OWNER) return errorResponse(403,'This account does not own CoolCode.');
    return null;
  } catch { return errorResponse(503,'GitHub identity check is unavailable.'); }
}

async function stats(db,url,now) {
  const days=Number(url.searchParams.get('days') || 7);
  if (![7,28].includes(days)) return errorResponse(400,'Choose 7 or 28 days.');
  const through=dayOf(now), from=dayOf(new Date(now.getTime()-(days-1)*86400000));
  const run=sql=>db.prepare(sql).bind(from,through);
  const [tools,daily,experiments,cards,reportCount]=await db.batch([
    run("SELECT tool,SUM(total) views FROM counts WHERE day BETWEEN ? AND ? AND type='pageview' GROUP BY tool ORDER BY views DESC,tool"),
    run("SELECT day,SUM(total) views FROM counts WHERE day BETWEEN ? AND ? AND type='pageview' GROUP BY day ORDER BY day"),
    run("SELECT experiment,variant,SUM(CASE WHEN type='impression' THEN total ELSE 0 END) impressions,SUM(CASE WHEN type='click' THEN total ELSE 0 END) clicks FROM counts WHERE day BETWEEN ? AND ? AND type IN ('impression','click') GROUP BY experiment,variant ORDER BY experiment,variant"),
    run("SELECT experiment,variant,tool,SUM(CASE WHEN type='impression' THEN total ELSE 0 END) impressions,SUM(CASE WHEN type='click' THEN total ELSE 0 END) clicks FROM counts WHERE day BETWEEN ? AND ? AND type IN ('impression','click') GROUP BY experiment,variant,tool ORDER BY experiment,variant,tool"),
    db.prepare("SELECT COUNT(*) count FROM reports WHERE status='open'"),
  ]);
  return {body:{days,from,through,totalViews:tools.results.reduce((n,row)=>n+row.views,0),openReports:reportCount.results[0].count,tools:tools.results,daily:daily.results,experiments:experiments.results,cards:cards.results}};
}

async function reports(db,url) {
  const before=url.searchParams.get('before');
  if (before && !/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z~[\da-f-]{36}$/.test(before)) return errorResponse(400,'Invalid report cursor.');
  const [when,id] = before ? before.split('~') : ['9999',''];
  const result=await db.prepare('SELECT id,tool,category,description,created,status FROM reports WHERE (created,id)<(?,?) ORDER BY created DESC,id DESC LIMIT 101').bind(when,id).all();
  const rows=result.results.slice(0,100), last=rows.at(-1);
  return {body:{reports:rows,next:result.results.length>100 ? last.created+'~'+last.id : null}};
}

async function handle(request,env) {
  const db=env.DB, url=new URL(request.url),path=url.pathname;
  const origin=request.headers.get('Origin');
  const publicPath=['/event','/report'].includes(path);
  const adminPath=['/admin/stats','/admin/reports'].includes(path)||/^\/admin\/reports\/[\da-f-]{36}$/.test(path);
  // Public catalogue IDs only: read-only deployment verification, no visitor data or writes.
  if (path === '/registry' && request.method === 'GET') {
    return {body: {schema: 'coolcode.tool-registry.v1', tool_ids: toolList}};
  }
  if (path === '/health' && request.method === 'GET') {
    // Compile against the expected tables without reading any visitor records.
    await db.prepare('SELECT counts.day, limits.bucket, reports.id, salts.day FROM counts, limits, reports, salts LIMIT 0').all();
    return {body: {ok: true}};
  }
  if (!publicPath && !adminPath) return errorResponse(404, 'Unknown endpoint.');
  if ((publicPath && origin!==ORIGIN) || (origin && origin!==ORIGIN)) return errorResponse(403,'Origin is not allowed.');
  if (request.method==='OPTIONS') return {status:204};
  if (adminPath) {
    const denied=await owner(request);
    if (denied) return denied;
    if (path==='/admin/stats'&&request.method==='GET') return stats(db,url,new Date());
    if (path==='/admin/reports'&&request.method==='GET') return reports(db,url);
    if (path.startsWith('/admin/reports/')&&request.method==='PATCH') {
      const input=await body(request,300);
      if (!['open','resolved'].includes(input.status)) return errorResponse(400,'Unknown report status.');
      const row=await db.prepare('UPDATE reports SET status=? WHERE id=? RETURNING id,status').bind(input.status,path.split('/').pop()).first();
      return row ? {body:{ok:true,...row}} : errorResponse(404,'Report not found.');
    }
    return errorResponse(405,'Unsupported method.');
  }
  if (request.method!=='POST') return errorResponse(405,'Unsupported method.');
  const isReport=path==='/report';
  const mime=(request.headers.get('content-type')||'').split(';')[0].trim().toLowerCase();
  if (!(isReport ? ['application/json'] : ['application/json','text/plain']).includes(mime)) return errorResponse(415,'Unsupported content type.');
  const input=await body(request,isReport?10000:1000);
  const row=isReport ? reportRecord(input) : eventRecord(input);
  if (!row) return errorResponse(400,isReport?'Check the tool, category and description.':'Invalid event.');
  const now=new Date();
  if (!await allowed(db,request,now,isReport?'report':'event')) return errorResponse(429,'Please try again later.');
  if (isReport) {
    const id=crypto.randomUUID();
    await db.prepare("INSERT INTO reports(id,tool,category,description,created,status) VALUES(?,?,?,?,?,'open')").bind(id,row.tool,row.category,row.description,now.toISOString()).run();
    return {status:201,body:{ok:true,id}};
  }
  await db.prepare('INSERT INTO counts(day,tool,experiment,variant,type,total) VALUES(?,?,?,?,?,1) ON CONFLICT(day,tool,experiment,variant,type) DO UPDATE SET total=total+1').bind(dayOf(now),row.tool,row.experiment,row.variant,row.type).run();
  return {status:204};
}

export default {
  async fetch(request,env) {
    const headers={'Cache-Control':cacheControl,Vary:'Origin','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer'};
    if (request.headers.get('Origin')===ORIGIN) {
      headers['Access-Control-Allow-Origin']=ORIGIN;
      headers['Access-Control-Allow-Methods']='GET, POST, PATCH, OPTIONS';
      headers['Access-Control-Allow-Headers']='Authorization, Content-Type';
      headers['Access-Control-Max-Age']='600';
    }
    let result;
    try { result=await handle(request,env); }
    catch (e) {
      if (e instanceof RangeError) result=errorResponse(413,'Request is too large.');
      else if (e instanceof SyntaxError || e instanceof TypeError && e.code==='ERR_ENCODING_INVALID_ENCODED_DATA') result=errorResponse(400,'Invalid JSON request.');
      else result=errorResponse(503,'Service temporarily unavailable.');
    }
    if (result.body) headers['Content-Type']='application/json; charset=utf-8';
    return new Response(result.body?JSON.stringify(result.body):null,{status:result.status||200,headers});
  },
};
